create extension if not exists pgcrypto;
create table institutions(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text not null default '',province text not null default '',canton text not null default '',contact_name text not null default '',type text not null check(type in('Escuela','Colegio','Jardín infantil','Otra')),status text not null default 'Sin contactar' check(status in('Sin contactar','Contactado','Respondió','Interesado','Cotización solicitada','Cliente','No interesado','No contactar')),last_contact_at timestamptz,notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create unique index institutions_email_active on institutions(lower(email)) where deleted_at is null;create index institutions_status on institutions(status) where deleted_at is null;
create table contacts(id uuid primary key default gen_random_uuid(),institution_id uuid not null references institutions(id) on delete cascade,name text not null,email text,phone text,role text,created_at timestamptz not null default now());
create table email_templates(id uuid primary key default gen_random_uuid(),name text not null,kind text not null,subject text not null,html text not null,is_default boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table campaigns(id uuid primary key default gen_random_uuid(),name text not null,subject text not null,html text not null,template_id uuid references email_templates(id),status text not null check(status in('Borrador','Programada','En ejecución','Pausada','Completada','Cancelada')),scheduled_at timestamptz,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index campaigns_status on campaigns(status);
create table campaign_recipients(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id) on delete cascade,institution_id uuid not null references institutions(id),email text not null,status text not null default 'Pendiente',created_at timestamptz not null default now(),unique(campaign_id,institution_id));
create table email_jobs(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id) on delete cascade,recipient_id uuid not null references campaign_recipients(id) on delete cascade,status text not null check(status in('pending','claimed','sent','failed','uncertain','rate_limited','auth_error')),idempotency_key text not null unique,attempts int not null default 0,available_at timestamptz not null default now(),claimed_at timestamptz,completed_at timestamptz,last_error text,created_at timestamptz not null default now());create index email_jobs_claim on email_jobs(status,available_at);
create table email_messages(id uuid primary key default gen_random_uuid(),campaign_id uuid references campaigns(id),recipient_id uuid references campaign_recipients(id),email text not null,subject text not null,gmail_message_id text unique,status text not null check(status in('sent','delivered','replied','failed','uncertain')),error text,sent_at timestamptz,delivered_at timestamptz,replied_at timestamptz,created_at timestamptz not null default now());create index messages_campaign on email_messages(campaign_id,created_at desc);
create table replies(id uuid primary key default gen_random_uuid(),institution_id uuid references institutions(id),campaign_id uuid references campaigns(id),gmail_message_id text not null unique,thread_id text,sender text not null,subject text not null,body_text text not null,followup_status text not null default 'Pendiente',received_at timestamptz not null,created_at timestamptz not null default now());
create table activity_logs(id uuid primary key default gen_random_uuid(),action text not null,entity_type text,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());create index activity_recent on activity_logs(created_at desc);
create table app_settings(key text primary key,value text not null,updated_at timestamptz not null default now());
create table suppression_list(id uuid primary key default gen_random_uuid(),email text not null,reason text not null default 'Solicitud del destinatario',source text not null default 'manual',created_at timestamptz not null default now());create unique index suppression_email on suppression_list(lower(email));
alter table institutions enable row level security;alter table contacts enable row level security;alter table campaigns enable row level security;alter table campaign_recipients enable row level security;alter table email_jobs enable row level security;alter table email_messages enable row level security;alter table replies enable row level security;alter table email_templates enable row level security;alter table activity_logs enable row level security;alter table app_settings enable row level security;alter table suppression_list enable row level security;
